<template><div class="portal-page"><header><h1>Estado de cuenta</h1><p>Actividad y saldo de tu cuenta</p></header><div class="card"><div class="filters"><label>Desde<input v-model="fromDate" type="date"></label><label>Hasta<input v-model="toDate" type="date"></label><button @click="fetch">Aplicar</button></div><div v-if="data"><div class="summary"><div><span>Cuenta</span><strong>{{data.client&&data.client.name}}</strong></div><div><span>Saldo inicial</span><strong>{{formatMoney(data.current_opening_balance!=null?data.current_opening_balance:data.opening_balance)}}</strong></div><div><span>Saldo final</span><strong>{{formatMoney(data.closing_balance)}}</strong></div></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Referencia</th><th>Descripción</th><th>Débito</th><th>Crédito</th><th>Saldo</th></tr></thead><tbody><tr v-for="(e,i) in data.entries" :key="i"><td>{{e.date}}</td><td>{{typeLabel(e.type)}}</td><td>{{e.ref}}</td><td>{{e.description}}</td><td>{{e.debit?formatMoney(e.debit):'—'}}</td><td>{{e.credit?formatMoney(e.credit):'—'}}</td><td>{{formatMoney(e.balance)}}</td></tr><tr v-if="!(data.entries&&data.entries.length)"><td colspan="7">No hay movimientos en este período</td></tr></tbody></table></div></div><div v-else class="empty">Selecciona un rango de fechas y presiona Aplicar para cargar tu estado de cuenta.</div></div></div></template><script>export default{data(){return{data:null,fromDate:'',toDate:''}},mounted(){this.fetch()},methods:{async fetch(){try{const{data}=await axios.get('/portal/statement',{params:{from_date:this.fromDate||undefined,to_date:this.toDate||undefined}});this.data=data}catch(_){this.data=null}},formatMoney(n){return Number(n||0).toLocaleString('es-HN',{minimumFractionDigits:2,maximumFractionDigits:2})},typeLabel(v){const s=(v||'').toLowerCase();return {sale:'Venta',payment:'Pago',opening_balance:'Saldo inicial',return:'Devolución',refund:'Reembolso'}[s]||v||'—'}}}</script><style scoped>header{margin-bottom:1.25rem}h1{margin:0}.card{background:var(--pc-surface);border:1px solid var(--pc-border);border-radius:var(--pc-radius);overflow:hidden}.filters{display:flex;gap:1rem;align-items:end;padding:1rem;flex-wrap:wrap}.filters label{display:grid;gap:.35rem}.filters input,.filters button{padding:.6rem .8rem;border:1px solid var(--pc-border-strong);border-radius:8px}.filters button{background:var(--pc-primary);color:#fff}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:.75rem;padding:1rem}.summary>div{padding:1rem;background:var(--pc-surface-alt);border-radius:8px;display:grid;gap:.3rem}.summary span{color:var(--pc-text-muted);font-size:.8rem}.table-wrap{overflow:auto;padding:0 1rem 1rem}table{width:100%;border-collapse:collapse}th,td{padding:.7rem;border-bottom:1px solid var(--pc-border);text-align:left}.empty{padding:3rem;text-align:center;color:var(--pc-text-muted)}@media(max-width:768px){.summary{grid-template-columns:1fr}}</style>